const rows = Array.isArray(msg.payload) ? msg.payload : [];

if (rows.length === 0) {
    node.warn('Origen no devolvio registros con FormaPago.');
    return [{ payload: { ok: true, accion: 'sin_datos', mensaje: 'Origen no tiene registros con FormaPago.' } }, null];
}

function esc(v) {
    if (v === null || v === undefined) return 'NULL';
    return `'${String(v).replace(/\\/g, '\\\\').replace(/'/g, "''")}'`;
}

const updates = rows.map(r =>
    `UPDATE TiposDeMovimiento SET FormaPago = ${esc(r.FormaPago)} WHERE idTiposDeMovimiento = ${r.idTiposDeMovimiento} AND (FormaPago IS NULL OR TRIM(FormaPago) = '')`
);

flow.set('fp_cola', updates);
flow.set('fp_total', updates.length);
flow.set('fp_ejecutados', 0);

return [
    { payload: { ok: true, accion: 'cola_lista', total: updates.length, mensaje: `Cola armada con ${updates.length} UPDATEs posibles.` } },
    { _arrancar: true }
];

const cola = flow.get('fp_cola') || [];

if (cola.length === 0) {
    const total = flow.get('fp_total') || 0;
    const ejecutados = flow.get('fp_ejecutados') || 0;
    return [{ payload: { ok: true, accion: 'cola_vacia', total, ejecutados, mensaje: `Listo. Se ejecutaron ${ejecutados} UPDATEs sobre ${total} registros evaluados.` } }, null];
}

const sql = cola.shift();
flow.set('fp_cola', cola);

msg.topic = sql;
return [null, msg];

